import pickle,time,json
from collections import defaultdict,Counter
from sage.all import matrix,ZZ
with open('workspace/agent4_johnson_image_degree6_generators.pickle','rb') as f:data=pickle.load(f);A=data['generators'];LW=data['lyndon_words']
weights=[]
for i in range(3):
 for w in LW:weights.append(tuple(w.count(j)-(j==i) for j in range(3)))
cols=defaultdict(list)
for j,w in enumerate(weights):cols[w].append(j)
rows=defaultdict(list)
for i,row in enumerate(A.rows()):
 nz=row.nonzero_positions()
 if nz:rows[weights[nz[0]]].append(i)
for w,rs in rows.items():
 cs=cols[w];C=A.matrix_from_rows_and_columns(rs,cs)
 H=C.hermite_form(algorithm='flint',include_zero_rows=False)
 ed=H.elementary_divisors()
 if any(x!=1 for x in ed):
  print('torsion weight',w,'block shape',C.dimensions(),'rank',H.nrows(),'SNF',Counter(map(int,ed)),flush=True)
  D,U,V=H.smith_form()
  i=next(i for i in range(min(D.dimensions())) if D[i,i]==3)
  delta=V.inverse().row(i)
  assert 3*delta==U.row(i)*H
  assert all(x in ZZ for x in delta)
  full=[0]*A.ncols()
  for j,c in zip(cs,delta):full[j]=int(c)
  out={'weight':list(w),'ambient_columns':cs,'generator_rows':rs,'delta_block':list(map(int,delta)),'delta_full':full,'three_delta_HNF_coeffs':list(map(int,U.row(i))),'lyndon_coordinates':[[j//len(LW),list(LW[j%len(LW)]),int(c)] for j,c in enumerate(full) if c]}
